create sequence public.seq_dispatch start 1;
create table public.dispatches(dispatch_id uuid primary key default gen_random_uuid(),dispatch_no text not null unique,customer_id uuid not null references public.customers(customer_id),order_id uuid references public.orders(order_id),finished_goods_id uuid not null references public.finished_goods(finished_goods_id),dispatch_date date not null default current_date,quantity numeric not null check(quantity>0),uom_id uuid not null references public.uoms(uom_id),vehicle_no text,driver_name text,dispatcher text,status text not null default'DISPATCHED' check(status in('READY','DISPATCHED','CANCELLED')),quickbooks_invoice_id text,created_at timestamptz not null default now(),created_by text not null default 'system',updated_at timestamptz not null default now(),updated_by text);
alter table public.gate_passes add column dispatch_id uuid references public.dispatches(dispatch_id);
alter table public.stock_ledger drop constraint stock_ledger_source_type;alter table public.stock_ledger add constraint stock_ledger_source_type check(source_transaction_type in('GRN','PRODUCTION_ENTRY','PACKING_RECORD','DISPATCH','ADJUSTMENT','OPENING_BALANCE'));
alter table public.production_orders drop constraint production_orders_status_check;alter table public.production_orders add constraint production_orders_status_check check(status in('ORDER_CONFIRMED','PRODUCTION_PLANNED','MATERIALS_PENDING','MATERIALS_READY','MACHINE_ASSIGNED','IN_SETUP','IN_PRODUCTION','ON_HOLD','QC_PENDING','QC_HOLD','QC_APPROVED','PACKING','FINISHED','READY_FOR_DISPATCH','DISPATCHED','CANCELLED'));
create or replace function public.dispatch_finished_goods(p_finished_goods uuid,p_gate_pass uuid,p_vehicle text,p_driver text,p_dispatcher text)returns uuid language plpgsql security definer set search_path=public as $$ declare v_dispatch uuid;v_no text;v_product uuid;v_qty numeric;v_uom uuid;v_location uuid;v_order uuid;v_customer uuid;v_po uuid;begin if not has_factory_role(auth.uid(),array['admin','store'])then raise exception'not authorized';end if;select fg.product_id,fg.quantity,fg.uom_id,fg.location_id,po.production_order_id,o.order_id,o.customer_id into v_product,v_qty,v_uom,v_location,v_po,v_order,v_customer from finished_goods fg join production_batches b using(production_batch_id)join production_orders po using(production_order_id)join order_items oi using(order_item_id)join orders o using(order_id)where fg.finished_goods_id=p_finished_goods and fg.status='AVAILABLE' for update of fg,po;if not found then raise exception'finished goods unavailable';end if;v_no:='DSP-'||to_char(current_date,'YYYYMMDD')||'-'||lpad(nextval('seq_dispatch')::text,4,'0');insert into dispatches(dispatch_no,customer_id,order_id,finished_goods_id,quantity,uom_id,vehicle_no,driver_name,dispatcher,created_by)values(v_no,v_customer,v_order,p_finished_goods,v_qty,v_uom,p_vehicle,p_driver,p_dispatcher,auth.uid()::text)returning dispatch_id into v_dispatch;insert into stock_ledger(product_id,quantity,uom_id,location_id,ownership,stock_category,source_transaction_type,source_transaction_id,reference_note,created_by)values(v_product,-v_qty,v_uom,v_location,'INTERCONVERTERS_OWNED','FINISHED_GOODS','DISPATCH',v_dispatch,v_no,auth.uid()::text);update finished_goods set status='DISPATCHED',updated_at=now(),updated_by=auth.uid()::text where finished_goods_id=p_finished_goods;update production_orders set status='DISPATCHED',updated_at=now(),updated_by=auth.uid()::text where production_order_id=v_po;if p_gate_pass is not null then update gate_passes set dispatch_id=v_dispatch,updated_at=now(),updated_by=auth.uid()::text where gate_pass_id=p_gate_pass and status='ISSUED';end if;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'Dispatch','dispatches',v_dispatch,jsonb_build_object('dispatch_no',v_no,'quantity',v_qty,'gate_pass_id',p_gate_pass));return v_dispatch;end $$;
alter table public.dispatches enable row level security;create policy factory_read_dispatches on public.dispatches for select using(has_factory_role(auth.uid(),array['admin','production_manager','store','accounts','viewer']));grant execute on function public.dispatch_finished_goods(uuid,uuid,text,text,text)to authenticated;
